### Packrat Parsing for Simple Statements

Consider the following PEG for assignment statements and procedure calls:

    statement ← assignment / call
    assignment ← designator ':=' designator
    call ← designator '(' designator ')'
    designator ← ident ('.' ident)*
    ident  ← 'a' / ... / 'z'

Implement the parser as a backtracking parser, following the rules from the course notes. You may use the commented version of method `literal`.

```python
class StatementBacktrack:
  src: str

  def literal(self, k: int, a: str):
    if self.src.startswith(a, k):
      return k + len(a)
    # if self.src.startswith(a, k): print('match', a, 'at', k); return k + len(a)
    # else: print('fail', a, 'at', k); return None

  def ident(self, k):
    if k < len(self.src) and 'a' <= self.src[k] <= 'z':
      return k + 1

  def designator(self, k):
    k = self.ident(k)
    if k is None:
      return None
    while True:
      k2 = self.literal(k, '.')
      if k2 is None:
        break
      k3 = self.ident(k2)
      if k3 is None:
        break
      k = k3
    return k

  def assignment(self, k):
    k1 = self.designator(k)
    if k1 is None:
      return None
    k2 = self.literal(k1, ':=')
    if k2 is None:
      return None
    return self.designator(k2)

  def call(self, k):
    k1 = self.designator(k)
    if k1 is None:
      return None
    k2 = self.literal(k1, '(')
    if k2 is None:
      return None
    k3 = self.designator(k2)
    if k3 is None:
      return None
    return self.literal(k3, ')')

  def statement(self, k):
    k2 = self.assignment(k)
    if k2 is not None:
      return k2
    return self.call(k)

  def parse(self, s: str):
    self.src = s
    return self.statement(0) == len(s)
