```python
pb = StatementBacktrack()
```

Here are some tests:

```python
assert pb.parse('a:=b')
assert pb.parse('a.b.c:=d.e')
assert pb.parse('a(b)')
assert pb.parse('a.b.c(d.e)')
assert not pb.parse('a')
assert not pb.parse('a=b')
assert not pb.parse('a.b.(c)')
assert not pb.parse('a..b:=c')
assert not pb.parse('a.b:=7')
```

Now write a memoizing parser:

```python
class StatementMemoizing(StatementBacktrack):
  def parse(self, s: str):
    self.src = s
    self.memo = {}
    return self.statement(0) == len(s)

  def _memo(self, name, k, fn):
    key = (name, k)
    if key not in self.memo:
      self.memo[key] = fn(k)
    return self.memo[key]

  def ident(self, k):
    return self._memo('ident', k, super().ident)

  def designator(self, k):
    return self._memo('designator', k, super().designator)

  def assignment(self, k):
    return self._memo('assignment', k, super().assignment)

  def call(self, k):
    return self._memo('call', k, super().call)

  def statement(self, k):
    return self._memo('statement', k, super().statement)
```

